/* eslint no-console:0 import/extensions:0 */
import 'fantd/src/popover-select/style/index.less';
import 'fantd/src/button/style/index.less';
import { PopoverSelect, Button, Icon } from 'fantd';
import React from 'react';
import ReactDOM from 'react-dom';

class Component extends React.Component {

    state = {
        value: 1,
    }
    render() {
        return (
            <div style={{ fontSize: 16 }}>
                <div> <a href="https://2x.ant.design/components/popover-cn/" target="_blank" rel="noopener noreferrer" >popover 属性可参考 antd文档</a> </div>
                <br />
                <PopoverSelect
                    placement="bottomLeft"
                    options={
                        [
                            { name: "价格从高到低", value: 1 },
                            { name: "价格从低到高", value: 2 },
                            { name: "面积从高到低", value: 3 },
                            { name: "面积从低到高", value: 4 },
                        ]
                    }
                >
                    <Button size="large" type="plain">无选中图标</Button>
                </PopoverSelect>
                <br />

                <PopoverSelect
                    placement="bottomLeft"
                    type="radio"
                    defaultValue={1}
                    options={
                        [
                            { name: "价格从高到低", value: 1 },
                            { name: "价格从低到高", value: 2 },
                            { name: "面积从高到低", value: 3 },
                            { name: "面积从低到高", value: 4 },
                        ]
                    }
                >
                    <Button size="large" type="plain">带选中</Button>
                </PopoverSelect>
                <br />

                <PopoverSelect
                    placement="bottomLeft"
                    type="radio"
                    defaultValue={1}
                    options={
                        [
                            { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 1 },
                            { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 2 },
                            { img: "https://file.fangline.cn/erp/menu_pic.png", name: "面积从高到低", value: 3 },
                            { img: "https://file.fangline.cn/erp/menu_video.png", name: "面积从低到高", value: 4 },
                        ]
                    }
                >
                    <Button size="large" type="plain">带图标</Button>
                </PopoverSelect>
                <br />

                <PopoverSelect
                    placement="bottomLeft"
                    type="radio"
                    value={this.state.value}
                    onSelect={(v) => this.setState({ value: v })}
                    options={
                        [
                            { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 1 },
                            { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 2 },
                            { img: "https://file.fangline.cn/erp/menu_pic.png", name: "面积从高到低", value: 3 },
                            { img: "https://file.fangline.cn/erp/menu_video.png", name: "面积从低到高", value: 4 },
                        ]
                    }
                >
                    <Button size="large" type="plain">受控组件</Button>
                </PopoverSelect>
                <br />

                <PopoverSelect
                    placement="bottomLeft"
                    type="radio"
                    defaultValue={1}
                    options={
                        [
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 1 },
                                { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 2 },
                                { img: "https://file.fangline.cn/erp/menu_pic.png", name: "面积从高到低", value: 3 },
                                { img: "https://file.fangline.cn/erp/menu_video.png", name: "面积从低到高", value: 4 },
                            ],
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 5 },
                            ],
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 6 },
                                { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 7 },
                            ],
                        ]
                    }
                >
                    <Button size="large" type="plain">分组</Button>
                </PopoverSelect>
                <br />

                <PopoverSelect
                    placement="bottomLeft"
                    title="更多"
                    defaultValue={1}
                    options={
                        [
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 1 },
                                { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 2 },
                                { img: "https://file.fangline.cn/erp/menu_pic.png", name: "面积从高到低", value: 3 },
                                { img: "https://file.fangline.cn/erp/menu_video.png", name: "面积从低到高", value: 4 },
                            ],
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 5 },
                            ],
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 6 },
                                { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 7 },
                            ],
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 8 },
                                { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 9 },
                            ],
                            [
                                { img: "https://file.fangline.cn/erp/xietixing_1.png", name: "价格从高到低", value: 10 },
                                { img: "https://file.fangline.cn/erp/daikandengji_1.png", name: "价格从低到高", value: 11 },
                            ],
                        ]
                    }
                >
                    <Button size="large" type="plain">带title</Button>
                </PopoverSelect>
                <br />

                <PopoverSelect
                    placement="bottomLeft"
                    title="更多"
                    defaultValue={1}
                    options={
                        [
                            [
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从高到低", value: 1 },
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从低到高", value: 2 },
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "面积从高到低", value: 3 },
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "面积从低到高", value: 4 },
                            ],
                            [
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从高到低", value: 5 },
                            ],
                            [
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从高到低", value: 6 },
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从低到高", value: 7 },
                            ],
                            [
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从高到低", value: 8 },
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从低到高", value: 9 },
                            ],
                            [
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从高到低", value: 10 },
                                { prefix: <Icon style={{marginRight:16,color:"red"}} type="right-square" />, name: "价格从低到高", value: 11 },
                            ],
                        ]
                    }
                >
                    <Button size="large" type="plain">自定义前缀</Button>
                </PopoverSelect>
                <br />
            </div>
        );
    }
}

ReactDOM.render(<Component />, document.getElementById('__react-content'));



